def compute(vars):
    current_portion = -vars["v1"]
    total_outstanding = vars["v2"]
    if total_outstanding == 0:
        return None
    value = current_portion / total_outstanding * 100
    return {
        "value": value,
        "trace": {
            "current_portion": current_portion,
            "total_outstanding": total_outstanding,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
